package com.example.rokidgeminisecretary;
import android.content.Context;import org.json.*;import java.nio.file.*;
public final class ConversationRecoveryStoreTest{
 static int n;static void ok(boolean b){if(!b)throw new AssertionError("recovery "+n);n++;}
 public static void main(String[]args)throws Exception{Context c=new Context(Files.createTempDirectory("loki-recovery-").toFile());String id="a".repeat(64);JSONObject body=new JSONObject().put("requestId","fixture-1234").put("message","SYNTHETIC_PRIVATE_TEXT").put("api_key","DO_NOT_STORE");ConversationRecoveryStore.save(c,id,"send",body);ok(ConversationRecoveryStore.list(c).length()==1);JSONObject item=ConversationRecoveryStore.read(c,id);ok(item.getJSONObject("payload").getString("message").equals("SYNTHETIC_PRIVATE_TEXT"));ok(!item.toString().contains("DO_NOT_STORE"));byte[] cipher=Files.readAllBytes(ConversationRecoveryStore.file(c,id).toPath());ok(!new String(cipher,java.nio.charset.StandardCharsets.ISO_8859_1).contains("SYNTHETIC_PRIVATE_TEXT"));ConversationRecoveryStore.save(c,id,"send",body);ok(ConversationRecoveryStore.list(c).length()==1);boolean changed=false;try{ConversationRecoveryStore.save(c,id,"send",new JSONObject(body.toString()).put("message","different"));}catch(Exception e){changed=true;}ok(changed);ok(ConversationRecoveryStore.read(c,id).getJSONObject("payload").getString("message").equals("SYNTHETIC_PRIVATE_TEXT"));
 for(int i=1;i<13;i++)ConversationRecoveryStore.save(c,String.format("%064x",i),"image-question",new JSONObject().put("requestId","fixture-image-"+i).put("message","image "+i).put("image","AQID").put("imageCount",2).put("kinds",new JSONArray().put("image").put("video")));ok(ConversationRecoveryStore.list(c).length()==10);JSONObject media=ConversationRecoveryStore.read(c,String.format("%064x",12)).getJSONObject("payload");ok(media.getString("image").equals("AQID"));ok(media.getJSONArray("kinds").getString(1).equals("video"));
 Path f=ConversationRecoveryStore.file(c,String.format("%064x",12)).toPath();f.toFile().setLastModified(System.currentTimeMillis()-ConversationRecoveryStore.TTL-1);ConversationRecoveryStore.list(c);ok(!Files.exists(f));boolean invalid=false;try{ConversationRecoveryStore.read(c,"../private");}catch(Exception e){invalid=true;}ok(invalid);
 System.out.println("PASS "+n+" encrypted recovery / retention / ID checks");}
}
